   104→      // parse(String) and startFileFromBeginning.
   105→      return (InputRowParser<T>) new TransformingStringInputRowParser(
   106→          parser.getParseSpec(),
   107→          ((StringInputRowParser) parser).getEncoding(),
   108→          this
   109→      );
