   119→
   120→  /**
   121→   * Create a {@link Transformer} from this TransformSpec, when the rows to be transformed do not have a known
   122→   * signature.
   123→   */
   124→  public Transformer toTransformer()
   125→  {
   126→    return new Transformer(this);
   127→  }
   128→
   129→  @Override
   130→  public boolean equals(final Object o)
   131→  {
   132→    if (this == o) {
