   147→  }
   148→
   149→  @Override
   150→  public String toString()
   151→  {
   152→    return "TransformSpec{" +
   153→           "filter=" + filter +
   154→           ", transforms=" + transforms +
   155→           '}';
   156→  }
   157→}
