    34→/**
    35→ *
    36→ */
    37→public class DimFilterUtils
    38→{
    39→  static final byte SELECTOR_CACHE_ID = 0x0;
    40→  static final byte AND_CACHE_ID = 0x1;
    41→  static final byte OR_CACHE_ID = 0x2;
    42→  static final byte NOT_CACHE_ID = 0x3;
    43→  static final byte EXTRACTION_CACHE_ID = 0x4;
    44→  static final byte REGEX_CACHE_ID = 0x5;
    45→  static final byte SEARCH_QUERY_TYPE_ID = 0x6;
    46→  static final byte JAVASCRIPT_CACHE_ID = 0x7;
    47→  static final byte SPATIAL_CACHE_ID = 0x8;
    48→  static final byte IN_CACHE_ID = 0x9;
    49→  static final byte BOUND_CACHE_ID = 0xA;
    50→  static final byte INTERVAL_CACHE_ID = 0xB;
    51→  static final byte LIKE_CACHE_ID = 0xC;
    52→  static final byte COLUMN_COMPARISON_CACHE_ID = 0xD;
    53→  static final byte EXPRESSION_CACHE_ID = 0xE;
    54→  static final byte TRUE_CACHE_ID = 0xF;
    55→  static final byte FALSE_CACHE_ID = 0x11;
    56→  public static final byte BLOOM_DIM_FILTER_CACHE_ID = 0x10;
    57→
    58→  public static final byte STRING_SEPARATOR = (byte) 0xFF;
    59→
    60→  static byte[] computeCacheKey(byte cacheIdKey, List<DimFilter> filters)
    61→  {
    62→    if (filters.size() == 1) {
    63→      return filters.get(0).getCacheKey();
    64→    }
    65→
    66→    byte[][] cacheKeys = new byte[filters.size()][];
    67→    int totalSize = 0;
    68→    int index = 0;
    69→    for (DimFilter field : filters) {
    70→      cacheKeys[index] = field.getCacheKey();
    71→      totalSize += cacheKeys[index].length;
    72→      ++index;
    73→    }
    74→
    75→    ByteBuffer retVal = ByteBuffer.allocate(1 + totalSize);
    76→    retVal.put(cacheIdKey);
    77→    for (byte[] cacheKey : cacheKeys) {
    78→      retVal.put(cacheKey);
    79→    }
    80→    return retVal.array();
    81→  }
    82→
    83→  /**
    84→   * Filter the given iterable of objects by removing any object whose ShardSpec, obtained from the converter function,
    85→   * does not fit in the RangeSet of the dimFilter {@link DimFilter#getDimensionRangeSet(String)}. The returned set
    86→   * contains the filtered objects in the same order as they appear in input.
    87→   *
    88→   * If you plan to call this multiple times with the same dimFilter, consider using
    89→   * {@link #filterShards(DimFilter, Iterable, Function, Map)} instead with a cached map
    90→   *
    91→   * @param dimFilter The filter to use
    92→   * @param input     The iterable of objects to be filtered
    93→   * @param converter The function to convert T to ShardSpec that can be filtered by
    94→   * @param <T>       This can be any type, as long as transform function is provided to convert this to ShardSpec
    95→   *
    96→   * @return The set of filtered object, in the same order as input
    97→   */
    98→  public static <T> Set<T> filterShards(DimFilter dimFilter, Iterable<T> input, Function<T, ShardSpec> converter)
    99→  {
   100→    return filterShards(dimFilter, input, converter, new HashMap<>());
   101→  }
   102→
   103→  /**
   104→   * Filter the given iterable of objects by removing any object whose ShardSpec, obtained from the converter function,
   105→   * does not fit in the RangeSet of the dimFilter {@link DimFilter#getDimensionRangeSet(String)}. The returned set
   106→   * contains the filtered objects in the same order as they appear in input.
   107→   *
   108→   * DimensionRangedCache stores the RangeSets of different dimensions for the dimFilter. It should be re-used
   109→   * between calls with the same dimFilter to save redundant calls of {@link DimFilter#getDimensionRangeSet(String)}
   110→   * on same dimensions.
   111→   *
   112→   * @param dimFilter           The filter to use
   113→   * @param input               The iterable of objects to be filtered
   114→   * @param converter           The function to convert T to ShardSpec that can be filtered by
   115→   * @param dimensionRangeCache The cache of RangeSets of different dimensions for the dimFilter
   116→   * @param <T>                 This can be any type, as long as transform function is provided to convert this to ShardSpec
   117→   *
   118→   * @return The set of filtered object, in the same order as input
   119→   */
   120→  public static <T> Set<T> filterShards(
   121→      final DimFilter dimFilter,
   122→      final Iterable<T> input,
   123→      final Function<T, ShardSpec> converter,
   124→      final Map<String, Optional<RangeSet<String>>> dimensionRangeCache
   125→  )
   126→  {
   127→    Set<T> retSet = new LinkedHashSet<>();
   128→
   129→    for (T obj : input) {
   130→      ShardSpec shard = converter.apply(obj);
   131→      boolean include = true;
   132→
   133→      if (dimFilter != null && shard != null) {
   134→        Map<String, RangeSet<String>> filterDomain = new HashMap<>();
   135→        List<String> dimensions = shard.getDomainDimensions();
   136→        for (String dimension : dimensions) {
   137→          Optional<RangeSet<String>> optFilterRangeSet = dimensionRangeCache
   138→              .computeIfAbsent(dimension, d -> Optional.ofNullable(dimFilter.getDimensionRangeSet(d)));
   139→
   140→          if (optFilterRangeSet.isPresent()) {
   141→            filterDomain.put(dimension, optFilterRangeSet.get());
   142→          }
   143→        }
   144→        if (!filterDomain.isEmpty() && !shard.possibleInDomain(filterDomain)) {
   145→          include = false;
   146→        }
   147→      }
   148→
   149→      if (include) {
   150→        retSet.add(obj);
   151→      }
   152→    }
   153→    return retSet;
   154→  }
   155→}
